    pytest.param(PACKET_975, V975, id="v975-without-whisker-scopes"),
    pytest.param(PACKET_1001, V1001, id="v1001"),
    pytest.param(PACKET_2168, V2168, id="v2168"),
    pytest.param(PACKET_2168_WITHOUT_SYSTEM_CATEGORIES, V2168_WITHOUT_SYSTEM_CATEGORIES, id="v2168-without-categories"),
