@pytest.mark.parametrize("version", [v975, v1001, v2168], ids=lambda version: version.__name__.rpartition(".")[2])
def test_serverbound_diagnostics_is_packet_315(version):
    assert version.PACKETS[315] is version.ServerboundDiagnosticsPacket


@pytest.mark.parametrize(("packet", "golden"), GOLDENS)
def test_serverbound_diagnostics_encodes_to_its_golden(packet, golden):
    assert bytes(packet) == golden


@pytest.mark.parametrize(("packet", "golden"), GOLDENS)
def test_serverbound_diagnostics_decodes_from_its_golden(packet, golden):
    assert type(packet).from_bytes(golden) == packet


def test_the_memory_categories_are_shared_between_975_and_1001():
    assert v975.MemoryCategory is v1001.MemoryCategory


def test_the_memory_categories_are_renumbered_at_2168():
    assert v1001.MemoryCategory is not v2168.MemoryCategory


@pytest.mark.parametrize(
    ("member", "value"),
    [
        pytest.param(v1001.MemoryCategory.COUNT, 92, id="v1001-count"),
        pytest.param(v2168.MemoryCategory.COUNT, 111, id="v2168-count"),
        pytest.param(v1001.MemoryCategory.BIOME_STORAGE, 6, id="v1001-biome-storage"),
        pytest.param(v2168.MemoryCategory.BIOME_STORAGE, 6, id="v2168-biome-storage"),
        pytest.param(v1001.MemoryCategory.CEREAL, 7, id="v1001-cereal"),
        pytest.param(v2168.MemoryCategory.BLOBS, 7, id="v2168-blobs"),
        pytest.param(v2168.MemoryCategory.CEREAL, 8, id="v2168-cereal"),
        pytest.param(v1001.MemoryCategory.PERSONA, 54, id="v1001-persona"),
        pytest.param(v2168.MemoryCategory.PERSONA_PIECES, 56, id="v2168-persona-pieces"),
        pytest.param(v2168.MemoryCategory.PERSONA_REPO, 61, id="v2168-persona-repo"),
        pytest.param(v1001.MemoryCategory.RENDERING_RENDER_REGISTRY, 60, id="v1001-rendering-render-registry"),
        pytest.param(v1001.MemoryCategory.RENDERING_LIBRARY, 61, id="v1001-rendering-library"),
        pytest.param(v2168.MemoryCategory.RENDERING_LIBRARY, 72, id="v2168-rendering-library"),
        pytest.param(v2168.MemoryCategory.RENDERING_RENDER_REGISTRY, 75, id="v2168-rendering-render-registry"),
        pytest.param(v1001.MemoryCategory.GAMEFACE_SCRIPT_ENGINE, 91, id="v1001-gameface-script-engine"),
        pytest.param(v2168.MemoryCategory.GAMEFACE_SCRIPT_ENGINE, 108, id="v2168-gameface-script-engine"),
        pytest.param(v2168.MemoryCategory.GAMEFACE_LAYOUT, 110, id="v2168-gameface-layout"),
    ],
)
def test_the_memory_category_ordinals_move_at_2168(member, value):
    assert member == value


@pytest.mark.parametrize(
    ("member", "value"),
    [
        pytest.param(v2193.MemoryCategory.GAMEFACE_LAYOUT, 109, id="v2193-gameface-layout"),
        pytest.param(v2193.MemoryCategory.COUNT, 110, id="v2193-count"),
        pytest.param(v2225.MemoryCategory.GAMEFACE_LAYOUT, 109, id="v2225-gameface-layout"),
        pytest.param(v2225.MemoryCategory.EXECUTABLE, 110, id="v2225-executable"),
        pytest.param(v2225.MemoryCategory.COUNT, 111, id="v2225-count"),
    ],
)
def test_the_memory_categories_gain_executable_at_2225(member, value):
    assert member == value


def test_a_v1001_category_byte_reads_as_another_category_at_2168():
    back = v1001.ServerboundDiagnosticsPacket.from_bytes(V1001)
    assert back.category_counters[0].category == v2168.MemoryCategory.MOLANG


def test_the_same_category_is_a_different_byte_either_side_of_2168():
    assert (V975[37], V2168_WITHOUT_SYSTEM_CATEGORIES[37]) == (0x35, 0x36)
    assert V975[:37] + V975[38:] == V2168_WITHOUT_SYSTEM_CATEGORIES[:37] + V2168_WITHOUT_SYSTEM_CATEGORIES[38:-2]


def test_a_v1001_diagnostics_body_does_not_decode_as_a_v2168_one():
    with pytest.raises(ValueError, match="at byte"):
        v2168.ServerboundDiagnosticsPacket.from_bytes(V1001)


def test_a_v2168_diagnostics_body_does_not_decode_as_a_v1001_one():
    with pytest.raises(ValueError, match="at byte"):
        v1001.ServerboundDiagnosticsPacket.from_bytes(V2168)
